def calculate_minimum_passengers():
    n = int(input())
    a_s = list(map(int, input().split()))

    current_passenger = 0
    min_passenger = 0

    for change in a_s:
        current_passenger += change
        min_passenger = min(min_passenger, current_passenger)

    if min_passenger < 0:
        print(abs(min_passenger))
    else:
        print(0)
